import json, os

inv = {}
if os.path.exists('inventory.json'):
    with open('inventory.json') as f:
        text = f.read().strip()
    if text:
        for k, v in json.loads(text).items():
            inv[str(k)] = int(v)

rejected = []
if os.path.exists('transactions.txt'):
    with open('transactions.txt') as f:
        lines = f.read().splitlines()
    for idx, raw in enumerate(lines, start=1):
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 3:
            rejected.append(idx)
            continue
        op = parts[0].lower()
        sku = parts[1]
        try:
            qty = int(parts[2])
        except ValueError:
            rejected.append(idx)
            continue
        if op == 'add':
            inv[sku] = inv.get(sku, 0) + qty
        elif op == 'remove':
            cur = inv.get(sku)
            if cur is None or cur - qty < 0:
                rejected.append(idx)
            else:
                inv[sku] = cur - qty
        else:
            rejected.append(idx)

with open('inventory_after.json', 'w') as f:
    json.dump(inv, f, indent=2, sort_keys=True)
    f.write('\n')

with open('rejected.txt', 'w') as f:
    for n in rejected:
        f.write(str(n) + '\n')

print('ok', inv, rejected)
